const raw = $input.first().json.output;
let recipe;
try {
  const cleaned = String(raw).replace(/```json|```/g, '').trim();
  recipe = JSON.parse(cleaned);
} catch (e) {
  throw new Error("Output Architetto non JSON: " + String(raw).slice(0, 200));
}
const required = ['exercise_name','target_joints','compensations_to_monitor','patient_instructions'];
for (const k of required) {
  if (!(k in recipe)) throw new Error('Manca campo: ' + k);
}
if (!Array.isArray(recipe.target_joints) || recipe.target_joints.length === 0) throw new Error('target_joints vuoto');
for (const tj of recipe.target_joints) {
  if (!Array.isArray(tj.joints) || tj.joints.length !== 3) {
    throw new Error(`target '${tj.id}' ha ${tj.joints?.length ?? 0} giunti, ne servono esattamente 3`);
  }
}
return [{ json: { recipe, _validated: true } }];

const raw = $input.first().json.output;
let critique;
try {
  critique = JSON.parse(String(raw).replace(/```json|```/g, '').trim());
} catch (e) {
  return [{ json: { approvato: true, motivo: 'Critic non parsabile, uso ricetta originale', ricetta_corretta: null, _parse_error: true } }];
}
if (typeof critique.approvato !== 'boolean') {
  critique.approvato = true;
  critique.motivo = critique.motivo || 'Campo approvato mancante, default true';
}
return [{ json: critique }];

const metrics = $input.first().json.body.metrics;
const recipe = $input.first().json.body.recipe;
const errori = [];
for (const target of recipe.target_joints || []) {
  const val = metrics[target.id];
  if (val === undefined || val === null) { errori.push(target.id + '_mancante'); continue; }
  const min = target.min_angle ?? target.min;
  const max = target.max_angle ?? target.max;
  if (min !== undefined && val < min) errori.push(target.id);
  if (max !== undefined && val > max) errori.push(target.id);
}
for (const comp of recipe.compensations_to_monitor || []) {
  const val = metrics[comp.id];
  if (val === undefined || val === null) continue;
  const limite = comp.max_allowed;
  if (limite !== undefined && val > limite) errori.push(comp.id);
}
const target_ok = errori.length === 0;
return [{ json: { target_ok, errori_riscontrati: errori } }];

const raw = $input.first().json.output;
let route;
try {
  route = JSON.parse(String(raw).replace(/```json|```/g, '').trim());
} catch (e) {
  return [{ json: { route: 'deep', focus: null } }];
}
if (!['fast','deep'].includes(route.route)) route.route = 'deep';
if (!('focus' in route)) route.focus = null;
return [{ json: route }];

