}
if (!parsed.plan_delta) parsed.plan_delta = { adjust_target: null, add_warmup_reps: null, add_rest_seconds: null, note: 'Nessuna modifica' };
return [{ json: parsed }];

const critique = $json;
const originalRecipe = $('Valida Ricetta').item.json.recipe;

function isRecipeValid(r) {
  if (!r || typeof r !== 'object') return false;
  if (!Array.isArray(r.target_joints) || r.target_joints.length === 0) return false;
  for (const tj of r.target_joints) {
    if (!Array.isArray(tj.joints) || tj.joints.length !== 3) return false;
  }
  return true;
}

if (critique.ricetta_corretta && isRecipeValid(critique.ricetta_corretta)) {
  return [{ json: { recipe: critique.ricetta_corretta, _corrected: true, _critic_note: critique.motivo } }];
}
// Se la correzione è invalida, usa l'originale con warning
return [{ json: {
  recipe: originalRecipe,
  _warning: critique.motivo + ' (correzione del Critic scartata perché invalida)',
} }];

