const raw = $input.first().json.output;
let parsed;
try {
  parsed = JSON.parse(String(raw).replace(/```json|```/g, '').trim());
} catch (e) {
  return [{ json: { action: 'invalid', error: 'Output non JSON: ' + String(raw).slice(0, 300), raw: String(raw).slice(0, 2000) } }];
}

if (parsed.action === 'clarify') {
  if (!Array.isArray(parsed.questions) || parsed.questions.length === 0) {
    return [{ json: { action: 'invalid', error: 'clarify senza questions valide' } }];
  }
  if (parsed.questions.length > 3) parsed.questions = parsed.questions.slice(0, 3);
  return [{ json: { action: 'clarify', questions: parsed.questions } }];
}

if (parsed.action !== 'generate' || !parsed.program) {
  return [{ json: { action: 'invalid', error: 'Azione non valida o programma mancante', raw: JSON.stringify(parsed).slice(0, 1000) } }];
}

const p = parsed.program;
if (!Array.isArray(p.steps) || p.steps.length === 0) {
  return [{ json: { action: 'invalid', error: 'steps vuoto o non array' } }];
}

// --- AUTO-FIX: target_joints array di array -> array di oggetti
for (const ex of p.steps) {
  if (Array.isArray(ex.target_joints)) {
    ex.target_joints = ex.target_joints.map((tj, idx) => {
      if (Array.isArray(tj)) {
        const joints = tj;
        const id = joints[1] || ('target_' + idx);
        return { id: id, joints: joints, min_angle: 0, max_angle: 180 };
      }
      return tj;
    });
  }
  if (Array.isArray(ex.compensations_to_monitor)) {
    ex.compensations_to_monitor = ex.compensations_to_monitor.map((c, idx) => {
      if (!c.id) {
        c.id = c.type === 'angle_from_vertical' ? 'trunk_lean' : (c.type === 'distance_vertical' ? ('dist_' + idx) : ('comp_' + idx));
      }
      if (!c.feedback_message) {
        c.feedback_message = c.type === 'angle_from_vertical' ? 'Mantieni la postura eretta' : 'Correggi la postura';
      }
      return c;
    });
  }
}

if (p.steps.length > 10) {
  return [{ json: { action: 'invalid', error: 'Troppi esercizi (' + p.steps.length + '), max 10' } }];
}

const warnings = [];
if (p.steps.length > 6) warnings.push(p.steps.length + ' esercizi (sopra linea guida di 5)');

for (let i = 0; i < p.steps.length; i++) {
  const ex = p.steps[i];
  const exReq = ['id', 'exercise_name', 'patient_instructions', 'target_joints', 'phases'];
  for (const k of exReq) {
    if (!(k in ex)) {
      return [{ json: { action: 'invalid', error: 'Esercizio ' + i + ' (' + (ex.id || 'senza id') + '): manca ' + k } }];
    }
  }
  if (!Array.isArray(ex.target_joints) || ex.target_joints.length === 0) {
    return [{ json: { action: 'invalid', error: 'Esercizio ' + ex.id + ': target_joints vuoto o non array' } }];
  }
  for (let j = 0; j < ex.target_joints.length; j++) {
    const tj = ex.target_joints[j];
    if (!tj || typeof tj !== 'object' || Array.isArray(tj)) {
      return [{ json: { action: 'invalid', error: 'Esercizio ' + ex.id + ' target[' + j + '] ancora invalido: ' + JSON.stringify(tj).slice(0, 200) } }];
    }
    if (!tj.id) {
      return [{ json: { action: 'invalid', error: 'Target[' + j + '] senza id' } }];
    }
    if (!Array.isArray(tj.joints) || tj.joints.length !== 3) {
      return [{ json: { action: 'invalid', error: 'Target ' + tj.id + ': joints non è array di 3' } }];
    }
  }
  if (!Array.isArray(ex.phases) || ex.phases.length === 0) {
    return [{ json: { action: 'invalid', error: 'Esercizio ' + ex.id + ': phases vuoto' } }];
  }
  if (ex.phases.length > 8) {
    return [{ json: { action: 'invalid', error: 'Esercizio ' + ex.id + ': ' + ex.phases.length + ' fasi, max 8' } }];
  }
  const targetIds = new Set(ex.target_joints.map(t => t.id));
  const validPhaseTypes = ['reps', 'hold', 'movement', 'rest', 'custom_rules'];
  for (const ph of ex.phases) {
    if (!validPhaseTypes.includes(ph.type)) {
      return [{ json: { action: 'invalid', error: 'Fase ' + (ph.id || '?') + ': tipo sconosciuto ' + ph.type } }];
    }
    if (ph.type !== 'rest' && ph.type !== 'custom_rules') {
      if (!Array.isArray(ph.targets) || ph.targets.length === 0) {
        return [{ json: { action: 'invalid', error: 'Fase ' + ph.id + ': senza targets' } }];
      }
      for (const t of ph.targets) {
        if (!targetIds.has(t.joint_id)) {
          return [{ json: { action: 'invalid', error: 'Fase ' + ph.id + ': joint_id ' + t.joint_id + ' non nei target. Disponibili: ' + JSON.stringify([...targetIds]) } }];
        }
      }
    }
    if (ph.type === 'hold' && typeof ph.hold_seconds !== 'number') {
      return [{ json: { action: 'invalid', error: 'Fase ' + ph.id + ': hold senza hold_seconds' } }];
    }
    if (ph.type === 'reps' && typeof ph.repetitions !== 'number') {
      return [{ json: { action: 'invalid', error: 'Fase ' + ph.id + ': reps senza repetitions' } }];
    }
    if (ph.type === 'rest' && typeof ph.duration_seconds !== 'number') {
      return [{ json: { action: 'invalid', error: 'Fase ' + ph.id + ': rest senza duration_seconds' } }];
    }
  }
}

if (warnings.length > 0) p._warnings = warnings;
return [{ json: { action: 'generate', program: p, _validated: true, _auto_fixed: true } }];

const raw = $input.first().json.output;
let critique;
try {
  critique = JSON.parse(String(raw).replace(/```json|```/g, '').trim());
} catch (e) {
  return [{ json: { approvato: true, motivo: 'Critic non parsabile, uso programma originale' } }];
}
if (typeof critique.approvato !== 'boolean') critique.approvato = true;
return [{ json: critique }];

const critique = $json;
const orig = $('Valida Programma1').item.json.program;
function isValid(p) {
  if (!p || !Array.isArray(p.steps) || p.steps.length === 0) return false;
  for (const ex of p.steps) {
    if (!Array.isArray(ex.phases) || ex.phases.length === 0) return false;
    if (!Array.isArray(ex.target_joints)) return false;
  }
  return true;
}
if (critique.programma_corretto && isValid(critique.programma_corretto)) {
  return [{ json: { action: 'generate', program: critique.programma_corretto, _corrected: true, _critic_note: critique.motivo } }];
}
return [{ json: { action: 'generate', program: orig, _warning: critique.motivo + ' (correzione scartata perché invalida)' } }];

const body = $input.first().json.body;
const metrics = body.metrics || {};
const targets = body.targets_to_check || [];
const comps = body.compensations_to_check || [];
const errori = [];

for (const t of targets) {
  const val = metrics[t.id];
  if (val === undefined || val === null) { errori.push(t.id + '_mancante'); continue; }
  if (t.min !== undefined && val < t.min) errori.push(t.id);
  if (t.max !== undefined && val > t.max) errori.push(t.id);
}
for (const c of comps) {
  const val = metrics[c.id];
  if (val === undefined || val === null) continue;
  if (c.max_allowed !== undefined && val > c.max_allowed) errori.push(c.id);
}

const target_ok = errori.length === 0;
return [{ json: { target_ok, errori_riscontrati: errori } }];

